SourceCode.Declaration:
/// <summary>
/// An item found during a count that is not on the journal ("Not on this journal"). The app
/// never adds journal lines; the server or planner resolves each one (create a line, investigate).
/// ClientId is a device-generated UUID, stable across retries. Timestamps are ISO 8601 UTC.
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountExceptionRow
{
    str  clientId;
    str  itemNumber;
    str  locationId;
    real quantity;
    str  batchId;
    str  serialId;
    str  note;
    str  capturedBy;
    str  capturedAtUtc;

}

Method.Source:
[DataMemberAttribute('ClientId')]
public str parmClientId(str _value = clientId)
{
    clientId = _value;
    return clientId;
}

